INSERT INTO pf.task_attachment(space_id,task_id,message_id,ordinal,extraction_id,source_kind,workspace_id,file_id,version_id,attachment_id,source_asset_id,source_sha256,text_sha256,display_name)
 SELECT #{actor.spaceId},t.id,m.id,#{ordinal},#{source.extractionId},#{source.sourceKind},#{source.workspaceId,jdbcType=OTHER},#{source.fileId,jdbcType=OTHER},#{source.versionId,jdbcType=OTHER},#{source.attachmentId,jdbcType=OTHER},#{source.sourceAssetId},#{source.sourceSha256},#{source.textSha256},#{source.name}
 FROM pf.task t JOIN pf.message m ON m.task_id=t.id AND m.space_id=t.space_id AND m.role='USER' WHERE t.id=#{task} AND t.space_id=#{actor.spaceId} AND t.creator_id=#{actor.userId}
